            assert_eq!(Gana::try_from(member.key_id()), Ok(member));
            assert_eq!(member.full_key(), format!("{}.{}", Kind::Gana.name(), member.key()));
            assert_eq!(member.full_key().parse::<Gana>(), Ok(member));
            assert_eq!(member.to_string().parse::<Gana>(), Ok(member));
